package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Explicit operator curation; never derives popularity or discloses operator free text. */
public class ExperienceCurations {
 static final String PATH="/api/admin/community/curations",RULE="R8C_CURATED_V1";
 static final List<String> FIELDS=List.of("experience_id","source_hash","priority","source_note","scope_confirmed","valid_from","valid_to");
 private final ReservationStore db;private final OperatorIdentity operators;private final ExperienceModeration experiences;
 public ExperienceCurations(ReservationStore db,OperatorIdentity operators,ExperienceModeration experiences){this.db=db;this.operators=operators;this.experiences=experiences;}
 static JsonNode input(String raw,boolean update){var b=CouponInput.parse(raw);var keys=new ArrayList<>(FIELDS);if(update)keys.add("expected_revision");CouponInput.exact(b,keys.toArray(String[]::new));ExperienceModeration.publicId(b.path("experience_id").asText());if(!b.path("source_hash").isTextual()||!b.get("source_hash").asText().matches("[a-f0-9]{64}")||!b.path("scope_confirmed").isBoolean()||!b.get("scope_confirmed").asBoolean()||!b.path("priority").isIntegralNumber()||!b.get("priority").canConvertToInt()||b.get("priority").asInt()<1||b.get("priority").asInt()>1000000)throw ReservationInput.bad();if(update)CouponInput.id(b.get("expected_revision"));DiagnosisServicePolicies.text(b.get("source_note"),2,256);if(!CouponInput.time(b.get("valid_to")).isAfter(CouponInput.time(b.get("valid_from"))))throw ReservationInput.bad();return b;}
 private void auth(OperatorActor a,boolean lock){operators.authorize(a,OperatorIdentity.Permission.COMMUNITY_CURATE,lock);}
 private void pageNumber(int p){if(p<1||p>1000000)throw ReservationInput.bad();}
 private ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"精选来源、版本或时间已变化，请重新读取");}
 private String hash(Object n){return AuthTokens.sha256(db.json(AssessmentPolicyInput.canonical(db.mapper.valueToTree(n))));}
 private JsonNode tree(Object n){return db.parse(db.json(n));}
 private Map<String,Object> source(String id,boolean lock){var value=experiences.publishedSource(id,lock);return Map.of("experience",value,"source_hash",hash(value));}
 private Map<String,Object> confirmed(JsonNode b){var s=source(b.path("experience_id").asText(),true);if(!Objects.equals(s.get("source_hash"),b.path("source_hash").asText())||!CouponInput.time(b.get("valid_from")).isAfter(db.now()))throw conflict();return s;}
 Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM experience_curation WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 Map<String,Object> view(Map<String,Object> r){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","experience_id","source_hash","priority","source_note","revision","status","rule_version"))out.put(k,r.get(k));out.put("scope_confirmed",true);out.put("source_snapshot",db.parse(r.get("source_snapshot")));for(String k:List.of("valid_from","valid_to","created_at","published_at","stopped_at"))out.put(k,iso(r.get(k)));return out;}
 public Map<String,Object> sources(OperatorActor a,int p){pageNumber(p);return db.reads.execute(tx->{auth(a,false);var candidates=experiences.curationSources(p);var out=new LinkedHashMap<>(candidates);out.put("items",((List<?>)candidates.get("items")).stream().map(e->Map.of("experience",e,"source_hash",hash(e))).toList());return out;});}
 public Map<String,Object> list(OperatorActor a,int p){pageNumber(p);return db.reads.execute(tx->{auth(a,false);long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM experience_curation",Long.class);return page(db.jdbc.queryForList("SELECT * FROM experience_curation ORDER BY id DESC LIMIT 20 OFFSET ?",(p-1)*20L).stream().map(this::view).toList(),total,p,20);});}
 public Map<String,Object> detail(OperatorActor a,long id){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.reads.execute(tx->{auth(a,false);return view(row(id,false));});}
 public JsonNode create(OperatorActor a,String key,JsonNode b){String normalized=WriteIntegrityService.normalizeKey(key),bodyHash=hash(b);return db.writes.execute(new Actor("operator_account",a.id()),"POST",PATH,key,b,()->auth(a,true),()->{
  var previous=db.jdbc.queryForList("SELECT id,submission_hash,creation_result FROM experience_curation WHERE created_by=? AND submission_key=?",a.id(),normalized);if(!previous.isEmpty()){var r=previous.get(0);if(!bodyHash.equals(r.get("submission_hash")))throw ReservationInput.bad();var old=db.parse(r.get("creation_result"));if(!old.isObject())throw new IllegalStateException("Curation receipt missing");var saved=db.mapper.convertValue(old,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});return new Change("CURATION_CREATE","experience_curation",number(r,"id"),Map.of(),Map.of(),saved,false);}
  var s=confirmed(b);long id=db.insert("INSERT INTO experience_curation(experience_id,source_hash,source_snapshot,priority,source_note,valid_from,valid_to,created_by,submission_key,submission_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",b.path("experience_id").asText(),b.path("source_hash").asText(),db.json(s.get("experience")),b.path("priority").asInt(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),a.id(),normalized,bodyHash,time(db.now()));var after=view(row(id,true));db.jdbc.update("UPDATE experience_curation SET creation_result=? WHERE id=?",db.json(after),id);return new Change("CURATION_CREATE","experience_curation",id,Map.of(),after,after);
 });}
 public JsonNode update(OperatorActor a,long id,String key,JsonNode b){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.writes.execute(new Actor("operator_account",a.id()),"PUT",PATH+"/"+id,key,b,()->auth(a,true),()->{var s=confirmed(b);var r=row(id,true);if(!"DRAFT".equals(r.get("status"))||number(r,"revision")!=b.path("expected_revision").asLong())throw conflict();var before=view(r);db.jdbc.update("UPDATE experience_curation SET experience_id=?,source_hash=?,source_snapshot=?,priority=?,source_note=?,valid_from=?,valid_to=?,revision=revision+1 WHERE id=?",b.path("experience_id").asText(),b.path("source_hash").asText(),db.json(s.get("experience")),b.path("priority").asInt(),b.path("source_note").asText(),time(CouponInput.time(b.get("valid_from"))),time(CouponInput.time(b.get("valid_to"))),id);var after=view(row(id,true));return new Change("CURATION_UPDATE","experience_curation",id,before,after,after);});}
 public JsonNode status(OperatorActor a,long id,String key,JsonNode b){com.autocare.platform.service.ServiceCatalog.validateId(id);return db.writes.execute(new Actor("operator_account",a.id()),"PUT",PATH+"/"+id+"/status",key,b,()->auth(a,true),()->{String target=b.path("status").asText();var initial=row(id,false);if(number(initial,"revision")!=b.path("expected_revision").asLong()||!(target.equals("PUBLISHED")?"DRAFT".equals(initial.get("status")):target.equals("STOPPED")&&"PUBLISHED".equals(initial.get("status"))))throw conflict();if(target.equals("PUBLISHED")){var current=source(initial.get("experience_id").toString(),true);if(!Objects.equals(current.get("source_hash"),initial.get("source_hash"))||!instant(initial.get("valid_from")).isAfter(db.now()))throw conflict();}var r=row(id,true);if(number(r,"revision")!=b.path("expected_revision").asLong()||!Objects.equals(initial.get("source_hash"),r.get("source_hash"))||!(target.equals("PUBLISHED")?"DRAFT".equals(r.get("status")):target.equals("STOPPED")&&"PUBLISHED".equals(r.get("status"))))throw conflict();var before=view(r);try{db.jdbc.update("UPDATE experience_curation SET status=?,revision=revision+1,published_at=?,stopped_at=? WHERE id=?",target,target.equals("PUBLISHED")?time(db.now()):r.get("published_at"),target.equals("STOPPED")?time(db.now()):null,id);}catch(org.springframework.dao.DuplicateKeyException e){throw conflict();}var after=view(row(id,true));return new Change("CURATION_STATUS","experience_curation",id,before,after,after);});}
 private boolean proof(Map<String,Object> r){if(!RULE.equals(r.get("rule_version")))return false;var audits=db.jdbc.queryForList("SELECT id,after_state FROM audit_log WHERE is_deleted=0 AND actor_type='operator_account' AND action='CURATION_STATUS' AND resource_type='experience_curation' AND resource_id=? AND JSON_UNQUOTE(JSON_EXTRACT(after_state,'$.status'))='PUBLISHED' AND JSON_EXTRACT(after_state,'$.revision')=?",r.get("id"),r.get("revision"));var latest=db.jdbc.queryForList("SELECT id FROM audit_log WHERE actor_type='operator_account' AND action='CURATION_STATUS' AND resource_type='experience_curation' AND resource_id=? ORDER BY id DESC LIMIT 1",r.get("id"));return audits.size()==1&&latest.size()==1&&Objects.equals(audits.get(0).get("id"),latest.get(0).get("id"))&&tree(view(r)).equals(db.parse(audits.get(0).get("after_state")));}
 public Map<String,Object> curated(VehicleOwner a,long vehicle){com.autocare.platform.service.ServiceCatalog.validateId(vehicle);return db.reads.execute(tx->{Object model=experiences.recipient(a,vehicle);var now=db.now();var out=new LinkedHashMap<String,Object>();out.put("vehicle_id",vehicle);out.put("model_id",model);out.put("selection_type","OPERATOR_CURATED");out.put("observed_at",now.toString());out.put("state",experiences.publicationEnabled()?"UNKNOWN":"UNAVAILABLE");var items=new ArrayList<Map<String,Object>>();out.put("items",items);if(model==null||!experiences.publicationEnabled())return out;
  var rows=db.jdbc.queryForList("SELECT * FROM experience_curation WHERE status='PUBLISHED' AND valid_from<=? AND valid_to>? AND JSON_EXTRACT(source_snapshot,'$.model_id')=? ORDER BY priority,id DESC LIMIT 20",time(now),time(now),model);
  for(var r:rows){if(!proof(r))continue;Map<String,Object> current;try{current=source(r.get("experience_id").toString(),false);}catch(ResponseStatusException e){if(e.getStatusCode().value()==404)continue;throw e;}var e=(Map<?,?>)current.get("experience");if(!Objects.equals(current.get("source_hash"),r.get("source_hash"))||!tree(e).equals(db.parse(r.get("source_snapshot")))||((Number)e.get("model_id")).longValue()!=((Number)model).longValue())continue;items.add(Map.of("curation_id",r.get("id"),"revision",r.get("revision"),"priority",r.get("priority"),"valid_from",iso(r.get("valid_from")),"valid_to",iso(r.get("valid_to")),"experience",e));}
  if(!items.isEmpty())out.put("state","CONFIGURED");return out;
 });}
}
